import asyncio, os, sys, json, base64
from playwright.async_api import async_playwright
H = os.path.dirname(os.path.abspath(__file__)); OUT = os.path.join(H, "shots_trk")
PHOTO = base64.b64encode(open(os.path.join(OUT, "checkin_test.jpg"), "rb").read()).decode()
SIDE = os.path.join(os.path.dirname(H), "build", "trk", "web_side_blue.png")
BANNER = """(()=>{ const R=document.querySelector('.jc-host').shadowRoot; const t=R.querySelector('.px-trk'); if(!t) return 'no band'; const p=t.querySelector('.px-trk__pic'); const im=p.querySelector('img'); return p.className+(im?' img '+im.naturalWidth+'x'+im.naturalHeight:''); })()"""
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); ctx = await b.new_context(viewport={"width":1440,"height":900})
        pg = await ctx.new_page(); errs=[]
        pg.on("pageerror", lambda e: errs.append(str(e)))
        await pg.goto("file://" + H + "/t9.html"); await pg.wait_for_timeout(1200)
        await pg.evaluate("__tg.loadSample25()"); await pg.wait_for_timeout(300)
        rid = await pg.evaluate("(()=>{ const r=__tg.STATE().ros.find(x=>!x.shop && __tg.trkPick(x).kind==='none' && /VNR 640/.test(x.model)); const U=__tg.UI(); U.view='ros'; U.selectedRo=r.id; __tg.render(); return r.id; })()"); await pg.wait_for_timeout(800)
        print("1 none:", await pg.evaluate(BANNER))
        n = await pg.evaluate("""(b64)=>new Promise(res=>{ const bin=atob(b64), a=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) a[i]=bin.charCodeAt(i); const f=new File([a],'IMG_2041.jpg',{type:'image/jpeg'}); const ro=__tg.getRO('%s'); __tg.JC.addFilesTo(ro,'pics',[f],k=>res(k)); })""" % rid, PHOTO); await pg.wait_for_timeout(900)
        print("2 after check-in photo added (%s):" % n, await pg.evaluate(BANNER))
        await pg.screenshot(path=os.path.join(OUT, "i_photo.png"), clip={"x":260,"y":60,"width":860,"height":260})
        await pg.locator(".px-trk__act").click(); await pg.wait_for_timeout(300)
        print("3 menu:", await pg.evaluate("[...document.querySelector('.jc-host').shadowRoot.querySelectorAll('.px-trk__menu b')].map(x=>x.textContent).join(' | ')"))
        await pg.screenshot(path=os.path.join(OUT, "i_menu.png"), clip={"x":260,"y":60,"width":860,"height":420})
        async with pg.expect_file_chooser() as fc:
            await pg.locator(".px-trk__menu button").first.click()
        f = await fc.value; await f.set_files(SIDE); await pg.wait_for_timeout(1200)
        print("4 after Add a picture:", await pg.evaluate(BANNER), "| lib:", await pg.evaluate("__tg.trkLib().map(e=>e.model+'/'+e.cut+'/'+String(e.src).slice(0,16)+'/'+e.src.length).join(', ')"))
        await pg.screenshot(path=os.path.join(OUT, "i_added.png"), clip={"x":260,"y":60,"width":860,"height":260})
        await pg.locator(".px-trk__act").click(); await pg.wait_for_timeout(300)
        print("5 menu:", await pg.evaluate("[...document.querySelector('.jc-host').shadowRoot.querySelectorAll('.px-trk__menu b')].map(x=>x.textContent).join(' | ')"))
        await pg.locator(".px-trk__menu button", has_text="Use the check-in photo").click(); await pg.wait_for_timeout(500)
        print("6 use photo:", await pg.evaluate(BANNER), await pg.evaluate("__tg.getRO('%s').trkUse" % rid))
        await pg.locator(".px-trk__act").click(); await pg.wait_for_timeout(200)
        await pg.locator(".px-trk__menu button", has_text="Use the model picture here").click(); await pg.wait_for_timeout(500)
        print("7 back to model:", await pg.evaluate(BANNER), await pg.evaluate("__tg.getRO('%s').trkUse" % rid))
        # outside click closes the menu
        await pg.locator(".px-trk__act").click(); await pg.wait_for_timeout(200)
        await pg.mouse.click(700, 700); await pg.wait_for_timeout(200)
        print("8 menu after outside click:", await pg.evaluate("!!document.querySelector('.jc-host').shadowRoot.querySelector('.px-trk__menu')"))
        await pg.locator(".px-trk__act").click(); await pg.wait_for_timeout(200)
        await pg.keyboard.press("Escape"); await pg.wait_for_timeout(200)
        print("8b menu after Escape:", await pg.evaluate("!!document.querySelector('.jc-host').shadowRoot.querySelector('.px-trk__menu')"), "still on RO:", await pg.evaluate("__tg.UI().selectedRo===%r" % rid))
        await pg.locator(".px-trk__act").click(); await pg.wait_for_timeout(200)
        await pg.locator(".px-trk__menu button", has_text="Remove the picture").click(); await pg.wait_for_timeout(500)
        print("9 removed:", await pg.evaluate(BANNER), "| lib:", await pg.evaluate("__tg.trkLib().map(e=>e.model).join(', ')"))
        await pg.evaluate("__tg.undoLast()"); await pg.wait_for_timeout(500)
        print("10 undo:", await pg.evaluate(BANNER), "| lib:", await pg.evaluate("__tg.trkLib().map(e=>e.model).join(', ')"))
        # RO list
        await pg.evaluate("(()=>{ const U=__tg.UI(); U.selectedRo=null; U.view='rolist'; __tg.render(); })()"); await pg.wait_for_timeout(1500)
        await pg.screenshot(path=os.path.join(OUT, "i_list.png"))
        print("11 list thumbs:", await pg.evaluate("(()=>{ const L=[...document.querySelectorAll('.rq-row .trk-th')]; return L.length+' thumbs: '+['','fr','ph','no'].map(c=>c+':'+L.filter(x=>c?x.classList.contains(c):x.className==='trk-th').length).join(' ')+' · ph loaded '+L.filter(x=>x.classList.contains('ph')).map(x=>x.querySelector('img').naturalWidth).join(','); })()"),
              "| overflow:", await pg.evaluate("(()=>{ const r=document.querySelector('.rq'); return r ? r.scrollWidth+' / '+r.clientWidth : 'none'; })()"))
        # settings
        await pg.evaluate("(()=>{ const U=__tg.UI(); U.view='profile'; U.pxSec='data'; __tg.render(); })()"); await pg.wait_for_timeout(800)
        await pg.locator("[data-trk-card]").scroll_into_view_if_needed(); await pg.wait_for_timeout(200)
        el = pg.locator(".px-card:has([data-trk-card])"); await el.screenshot(path=os.path.join(OUT, "i_settings.png"))
        before = await pg.evaluate("__tg.STATE().ros.filter(x=>!x.shop && __tg.trkPick(x).kind==='model' && __tg.trkPick(x).entry.id==='st-white').length")
        await pg.locator('[data-trk-ed="st-white"][data-f="years"]').fill("2015-2024"); await pg.keyboard.press("Tab"); await pg.wait_for_timeout(400)
        after = await pg.evaluate("__tg.STATE().ros.filter(x=>!x.shop && __tg.trkPick(x).kind==='model' && __tg.trkPick(x).entry.id==='st-white').length")
        print("12 VNL 760 years 2018-2024 -> 2015-2024: ROs", before, "->", after)
        await pg.locator('[data-trk-ed="st-white"][data-f="years"]').fill("abc"); await pg.keyboard.press("Tab"); await pg.wait_for_timeout(400)
        print("13 bad years kept:", await pg.evaluate("__tg.trkLib().find(e=>e.id==='st-white').years"), "| toast:", await pg.evaluate("[...document.querySelectorAll('.toast,.px-toast,[class*=toast]')].map(x=>x.textContent.trim()).filter(Boolean).slice(-1).join('')"))
        print("14 shop keys has truckPics:", await pg.evaluate("'truckPics' in (__tg.pgShopData ? (__tg.pgShopData()||{}) : {})"))
        print("errs", errs[:5])
        await b.close()
asyncio.run(main())
